        '[[toast.grp]] · [[toast.position]]: where they appear, “[[toast.pos.top]]” (default), “[[toast.pos.topRight]]” or “[[toast.pos.bottom]]”. [[toast.size]]: “[[toast.sz.small]]”, “[[toast.sz.normal]]” (default) or “[[toast.sz.large]]”.',
        '[[toast.grp]] · [[toast.position]]: wo sie erscheinen, „[[toast.pos.top]]“ (Standard), „[[toast.pos.topRight]]“ oder „[[toast.pos.bottom]]“. [[toast.size]]: „[[toast.sz.small]]“, „[[toast.sz.normal]]“ (Standard) oder „[[toast.sz.large]]“.',
        '[[toast.grp]] · [[toast.position]] : où ils apparaissent, « [[toast.pos.top]] » (par défaut), « [[toast.pos.topRight]] » ou « [[toast.pos.bottom]] ». [[toast.size]] : « [[toast.sz.small]] », « [[toast.sz.normal]] » (par défaut) ou « [[toast.sz.large]] ».',
